"""Generate Sources/OmniVoiceMLX/LanguageMap.swift from omnivoice.utils.lang_map.

Run with the reference env:
    /tmp/omnivoice/.venv/bin/python scripts/gen_language_map.py
"""

import json
import pathlib

from omnivoice.utils.lang_map import LANG_IDS, LANG_NAME_TO_ID

out = pathlib.Path(__file__).resolve().parent.parent / "Sources/OmniVoiceMLX/LanguageMap.swift"
ids = sorted(LANG_IDS)
names = sorted(LANG_NAME_TO_ID.items())
lines = [
    "// Generated by scripts/gen_language_map.py from omnivoice.utils.lang_map. Do not edit.",
    "",
    "enum LanguageMap {",
    "    /// `LANG_IDS`",
    "    static let ids: Set<String> = [",
]
lines += [f"        {json.dumps(i, ensure_ascii=False)}," for i in ids]
lines += ["    ]", "", "    /// `LANG_NAME_TO_ID` (lower-case names)", "    static let nameToId: [String: String] = ["]
lines += [
    f"        {json.dumps(k, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)},"
    for k, v in names
]
lines += ["    ]", "}", ""]
out.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {out} ({len(ids)} ids, {len(names)} names)")
